// TODO: Extract UserAvatar and QuestItem as helper components in this file

const USER = { name: 'Aria', avatar: '/aria.png', xp: 1200 };
const QUESTS = [
  { id: 1, title: 'Defeat the Shadow Wyrm' },
  { id: 2, title: 'Recover the Lost Tome' },
];

export default function UserProfile() {
  return (
    <div>
      <img data-testid="avatar" src={USER.avatar} alt={USER.name} />
      <p>{USER.name} — {USER.xp} XP</p>
      <ul>
        {QUESTS.map(q => (
          <li key={q.id} data-testid="quest-item">{q.title}</li>
        ))}
      </ul>
    </div>
  );
}
